package com.nigson.commerce.cart;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.pricing.PricingAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
public final class CartService {
 private final CartRepository repository;private final PricingAuthority authority;private final JdbcTemplate jdbc;private final PlatformStore commands;private final AuditWriter audit;private final io.micrometer.core.instrument.MeterRegistry metrics;private final TransactionTemplate reads;
 public CartService(CartRepository repository,PricingAuthority authority,JdbcTemplate jdbc,PlatformStore commands,AuditWriter audit,io.micrometer.core.instrument.MeterRegistry metrics,org.springframework.transaction.PlatformTransactionManager manager){this.repository=repository;this.authority=authority;this.jdbc=jdbc;this.commands=commands;this.audit=audit;this.metrics=metrics;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(3);}
 private void organization(ActorAssertion.Actor actor,UUID organization,boolean lock){if(organization!=null)authority.organization(actor,organization,lock);}
 private CartValues.Cart owner(ActorAssertion.Actor actor,UUID id,boolean lock){var cart=repository.find(actor.party(),id,lock);organization(actor,cart.organizationId(),lock);return cart;}
 public CartValues.Cart get(ActorAssertion.Actor actor,UUID id){authority.require(actor,"CUSTOMER");return reads.execute(s->{jdbc.execute("SET LOCAL statement_timeout='1s'");authority.require(actor,"CUSTOMER");return owner(actor,id,false);});}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,Object input,UUID correlation,java.util.function.Supplier<PlatformStore.Response> change){authority.require(actor,"CUSTOMER");ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();try{return commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(input),db->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");authority.stabilize(actor,"CUSTOMER");return change.get();});}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private void evidence(ActorAssertion.Actor actor,AuditValues.Action action,UUID cart,long before,long after,UUID correlation,String operation){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,AuditValues.Resource.CART,cart,correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("version",before),Map.of("version",after),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.cart.commands","operation",operation).increment();}});}
 public CartValues.Cart create(ActorAssertion.Actor actor,CartValues.Create input,String key,UUID correlation){authority.require(actor,"CUSTOMER");organization(actor,input.organizationId(),false);var response=execute(actor,"API-032",key,input,correlation,()->{organization(actor,input.organizationId(),true);var result=repository.create(actor.party(),input,actor.party().toString());var after=result.cart();if(result.created())evidence(actor,AuditValues.Action.CART_CREATE,after.id(),0,after.version(),correlation,"CREATE");return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),after.id());});var after=EventCodec.JSON.treeToValue(response.body(),CartValues.Cart.class);organization(actor,after.organizationId(),false);return after;}
 public CartValues.Cart set(ActorAssertion.Actor actor,UUID id,UUID sku,long expected,CartValues.Quantity input,String key,UUID correlation){authority.require(actor,"CUSTOMER");owner(actor,id,false);CartValues.version(expected);var response=execute(actor,"API-034",key,Map.of("id",id,"sku",sku,"version",expected,"body",input),correlation,()->{owner(actor,id,true);var after=repository.set(actor.party(),id,sku,expected,input,actor.party().toString());evidence(actor,AuditValues.Action.CART_SET,id,expected,after.version(),correlation,"SET");return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),id);});return EventCodec.JSON.treeToValue(response.body(),CartValues.Cart.class);}
 public CartValues.Removed remove(ActorAssertion.Actor actor,UUID id,UUID sku,long expected,String key,UUID correlation){authority.require(actor,"CUSTOMER");owner(actor,id,false);CartValues.version(expected);var response=execute(actor,"API-035",key,Map.of("id",id,"sku",sku,"version",expected),correlation,()->{owner(actor,id,true);var after=repository.remove(actor.party(),id,sku,expected,actor.party().toString());evidence(actor,AuditValues.Action.CART_REMOVE,id,expected,after.version(),correlation,"REMOVE");return new PlatformStore.Response(204,EventCodec.JSON.valueToTree(after),id);});return EventCodec.JSON.treeToValue(response.body(),CartValues.Removed.class);}
}
